# Generated by build.py from recipe.yml for recipe gs-sign-with-an-hmac-key. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'store/photos', 'writable/photos' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'note.txt'), "a note`n")
[IO.File]::WriteAllText((Join-Path $PWD 'store/photos/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'writable/photos/hello.txt'), "hello from surl`n")
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1,DNS:storage.googleapis.com"'
$server0 = Start-Process surl -ArgumentList '--directory', 'store', '--cert', 'server.pem', '--key', 'server.key', '--user', 'GOOGTESTKEY:s3cret', '--user', ':ya29.t0ken', 'gs://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -sS --cacert server.pem --connect-to ::127.0.0.1:8080 -u GOOGTESTKEY:s3cret gs://photos/hello.txt --next -sS --cacert server.pem --connect-to ::127.0.0.1:8080 --oauth2-bearer ya29.t0ken gs://photos/hello.txt } finally { Stop-Process $server0 }
